  await new Promise(ok => { f.onload = ok; f.src = r; });
  await new Promise(ok => setTimeout(ok, 2500));
  const d = f.contentDocument; const W = f.contentWindow.innerWidth;
  const largos = [...d.querySelectorAll('main *')].filter(e => { const b = e.getBoundingClientRect(); return b.right > W + 1 && getComputedStyle(e).position !== 'fixed' && !e.closest('[class*=overflow-x], [class*=snap-x], ul[class*=overflow]'); }).slice(0,3).map(e => e.tagName + '.' + (e.className?.baseVal ?? e.className).toString().slice(0,40));
  out.push(`${r} -> scrollW=${d.documentElement.scrollWidth}/${W} ${largos.length ? 'LARGOS: '+largos.join(', ') : ''}`);
}
